        /** @description The initiate onboarding post DTO contains properties necessary for initiating the onboarding processes in GO. */
        InitiateOnboardingPostDto: {
            /**
             * Format: uuid
             * @description The applicationkey, representing the integrated application that is to be onboarded on client(s).
             *     Must be set in the POST call initiating the onboarding.
             * @example 1ed94aa6-b176-4c89-baa9-da3d240ac1e9
             */
            ApplicationKey?: string;
            /**
             * @description The organization number of the PowerOffice Go client that are to onboard the integrated application.
             *     If set, only this client will be presented to the user that must authorize the integration.
             *     If not set, the user will be presented a list of all clients the user have acccess to onboard, enabling onboarding of multiple clients in one process.
             * @example 980386465
             */
            ClientOrganizationNo?: string | null;
            /**
             * Format: uri
             * @description The redirect uri we will route to if the user successfully authorize onboarding on client(s).
             *     The uri need to be whitelisted by the api team before use, and this must be done separately for the demo and production environments.
             *     Note that the uri is allowed to be https://localhost in demo environment (does not need explicit whitelisting by api team).
             *     The system validate the domain, sub-domain and path used, but any parameters beyond that are ignored (and as such, any "?to=" variants can be used as the integrating party see fit).
             * @example https://auth.v2.integration.io/redirect
             */
            RedirectUri?: string | null;
        };
        /** @description The initiate onboarding response DTO contains properties necessary for (continuing) the onboarding processes in external system. */
        InitiateOnboardingResponseDto: {
            /**
             * Format: uri
             * @description The temporary Url to be used in the process of user authentication and user authorization of onboarding the integrated application.
             * @example http://identity.poweroffice.net/ApiAuthV2?token=iQcF9czVruLZQbhXyMTt7a11IyTDwZEwU1MifUbYN5RTy4I6sfoOX3HM2u5huwc7hz7SqRTLMIKkuiktiU1bWglYJd48uVv5QIZe2lhqPSGxJBQMMn9yTGWzn6I8BqKK
             */
            readonly TemporaryUrl?: string | null;
            /**
             * Format: date-time
             * @description The timestamp of when the temporary Url will expire.
             * @example 2021-09-30T08:03:00.0000000+00:00
             */
            readonly ValidUntilDateTimeOffset?: string;
        };
        /**
         * @description <p>Members:</p><ul><li><i>PassportNumber</i> - Passport number</li><li><i>NationalIdentityNumber</i> - National identity number (Social Security Number)</li><li><i>TaxIdentificationNumber</i> - Tax identification number</li><li><i>ValueAddedTaxIdentificationNumber</i> - Value added tax identification number</li></ul>
         * @enum {string|null}
         */
        InternationalIdType: "PassportNumber" | "NationalIdentityNumber" | "TaxIdentificationNumber" | "ValueAddedTaxIdentificationNumber" | null;
        /**
         * @description <p>Members:</p><ul><li><i>Shared</i> - The fees are shared between the sender and the receiver.</li><li><i>Sender</i> - The sender pays all fees.</li><li><i>Receiver</i> - The receiver pays all fees.</li></ul>
         * @enum {string|null}
         */
        InternationalPaymentFeeDistribution: "Shared" | "Sender" | "Receiver" | null;
        /** @description The available properties when inviting users to Go. */
        InviteUserPostDto: {
            /**
             * Format: uuid
             * @description The access role id the user have on the client.
             * @example 09ab6bcf-4219-4149-8283-6b6a7342bfd9
             */
            AccessRoleId: string;
            /**
             * @description The e-mail address of the user.
             * @example abc@test.yxz
             */
            EmailAddress: string | null;
            /**
             * @description The first name of the user.
             * @example Espen
             */
            FirstName: string | null;
            /**
             * Format: date
             * @description From date, inclusive.
             *     The user will have access to the client from this date.
             *     If not set, the user will have access from the day the user accept the invitation.
             * @example 2024-01-01
             */
            FromDate?: string | null;
            /**
             * @description Indicates whether the user should be added as an employee on the client.
             *     If true, an employee object will be created and linked to the user after the invitation is accepted.
             * @example true
             */
            InviteAsEmployee?: boolean | null;
            /**
             * @description The last name of the user.
             * @example Askeladd
             */
            LastName: string | null;
            /**
             * Format: date
             * @description To date, inclusive.
             *     The user will have access to the client until and including this date.
             *     Afterwards, the user is deactivated on the client.
             *     If not set, the user will have no time restricted access.
             * @example 2024-01-31
             */
            ToDate?: string | null;
        };
        /**
         * @description <p>Members:</p><ul><li><i>PdfByEmail</i> - Invoice will be delivered as email with PDF as attachment.
         *                     Can only be used if the customer have an e-mail address registered (either eMailAddress or invoiceEmailAddress).</li><li><i>Print</i> - Invoice will be printed and delivered physically.
         *                     "Sending" the invoice in Go will generate a PDF for download and print.</li><li><i>EHF</i> - Invoice will be delivered over EHF.
         *                     Can only be set if the customers organizationNumber is set and the number is registered in ELMA.</li><li><i>AvtaleGiro</i> - Invoice will be delivered over AvtaleGiro.
         *                     Cannot be set directly (set by the customer in an external process).</li><li><i>External</i> - Invoice will be prepared for delivery over an external third party integration.
         *                     Can only be set if the client have such an integration active.</li><li><i>Efaktura</i> - Invoice will be delivered by Efaktura.
         *                     Cannot be set directly (set by the customer on an external process).</li><li><i>Factoring</i> - The invoice will be prepared for delivered over an external third party factoring integration.
         *                     Can only be set if the client have such an integration active.</li></ul>
         * @enum {string|null}
         */
        InvoiceDeliveryType: "PdfByEmail" | "Print" | "EHF" | "AvtaleGiro" | "External" | "Efaktura" | "Factoring" | null;
